// Start launches the plugin subprocess, runs the domain Plugin.Handshake, marks
// the plugin serving, and arms the crash/restart monitor. It is idempotent: a
// second Start on an already-serving plugin is a no-op. The plugin runs on a
// context independent of this call's context so it outlives the request that
// started it; Stop tears it down.
func (m *Manager) Start(ctx context.Context, pluginID string) error {
	m.mu.Lock()
	e, ok := m.plugins[pluginID]
	if !ok {
		m.mu.Unlock()
		return notLoadedErr(pluginID)
	}
	if e.state == stateServing {
		m.mu.Unlock()
		return nil
	}
	if e.runCtx == nil {
		e.runCtx, e.runCancel = context.WithCancel(context.Background())
		e.stopCh = make(chan struct{})
	}
	runCtx, stopCh := e.runCtx, e.stopCh
	m.mu.Unlock()

	if err := m.doLaunch(ctx, e); err != nil {
		return fmt.Errorf("plugin: start %q: %w", pluginID, err)
	}
	go m.monitor(runCtx, e, stopCh)
	return nil
}

// Stop sends the domain Shutdown RPC (best-effort, within shutdownGrace), kills
// the subprocess (go-plugin's Kill = SIGTERM then SIGKILL fallback), and stops
// the monitor. Idempotent; safe to call on a plugin that never started.
func (m *Manager) Stop(_ context.Context, pluginID string) error {
	m.mu.Lock()
	e, ok := m.plugins[pluginID]
	if !ok {
		m.mu.Unlock()
		return notLoadedErr(pluginID)
	}
	if e.stopped {
		m.mu.Unlock()
		return nil
	}
	e.stopped = true
	rp := e.rp
	cancel := e.runCancel
	stopCh := e.stopCh
	m.mu.Unlock()

	if stopCh != nil {
		close(stopCh)
	}
	if cancel != nil {
		cancel()
	}
	if rp == nil {
		m.markStopped(e)
		return nil
	}
	sctx, scancel := context.WithTimeout(context.Background(), shutdownGrace)
	defer scancel()
	_, _ = rp.pconn.Shutdown(sctx, &pluginv1.ShutdownRequest{Reason: "manager stop"})
	rp.kill()
	m.markStopped(e)
	return nil
}

// markStopped records the stopped state after the subprocess is gone.
func (m *Manager) markStopped(e *pluginEntry) {
	m.mu.Lock()
	e.rp = nil
	e.state = stateNotServing
	e.message = "stopped"
	e.lastChecked = m.now()
	m.mu.Unlock()
}

// Status returns the plugin's current Health: the manager-tracked state (which
// reflects the substrate handshake + restart outcomes) plus the restart count.
// In MVP the domain Health RPC poll (§7.3, every 30s) is folded into this
// manager-tracked state rather than driven by a separate poller.
func (m *Manager) Status(pluginID string) (Health, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	e, ok := m.plugins[pluginID]
	if !ok {
		return Health{}, notLoadedErr(pluginID)
	}
	e.lastChecked = m.now()
	return Health{
		State:         e.state,
		Message:       e.message,
		Restarts:      e.restarts,
		LastCheckedAt: e.lastChecked,
	}, nil
}

// Logs returns the plugin's captured stderr tail (plugin-admin-surfaces D3),
// oldest line first, as a detached copy the caller may mutate freely. The ring
// is per plugin entry — allocated at Load, never cleared — so the tail carries
// the union of every launch of the same plugin. An unknown plugin id errors
// (notLoadedErr, the Status/Stop rule); a known one never does.
func (m *Manager) Logs(pluginID string) ([]string, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	e, ok := m.plugins[pluginID]
	if !ok {
		return nil, notLoadedErr(pluginID)
	}
	return e.logs.lines(), nil
}

// doLaunch starts the subprocess (via launchFn), runs the domain Handshake, and
// records the live handles + serving state. On any failure it kills the partial
// process and returns the error without changing state to serving.
func (m *Manager) doLaunch(ctx context.Context, e *pluginEntry) error {
	rp, err := m.launchFn(ctx, e)
	if err != nil {
		return fmt.Errorf("launch: %w", err)
	}
	hctx, cancel := context.WithTimeout(ctx, handshakeTimeout)
	hr, err := rp.pconn.Handshake(hctx, &pluginv1.HandshakeRequest{CoreVersion: m.deps.CoreVersion})
	cancel()
	if err != nil {
		rp.kill()
		return fmt.Errorf("handshake: %w", err)
	}
	m.mu.Lock()
	e.rp = rp
	e.handshake = hr
	e.state = stateServing
	e.message = ""
	e.consecFails = 0
	e.lastChecked = m.now()
	m.mu.Unlock()
	return nil
}

// monitor polls for an unexpected subprocess exit and, on detecting one (and
// only one at a time — handleExit guards re-entrancy), drives the restart loop.
func (m *Manager) monitor(ctx context.Context, e *pluginEntry, stopCh <-chan struct{}) {
	t := time.NewTicker(m.pollInterval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-stopCh:
			return
		case <-t.C:
		}
		m.mu.Lock()
		exited := e.rp != nil && e.rp.exited()
		busy := e.restarting
		failed := e.state == stateFailed
		stopped := e.stopped
		m.mu.Unlock()
		if exited && !failed && !busy && !stopped {
			m.handleExit(ctx, e)
		}
	}
}

// handleExit runs the §7.3 restart sequence: exponential-backoff relaunch until
// the plugin serves again or 3 consecutive attempts fail (then failed). It is
// re-entrancy-guarded so only one restart sequence runs per plugin at a time.
func (m *Manager) handleExit(ctx context.Context, e *pluginEntry) {
	m.mu.Lock()
	if e.stopped || e.restarting || e.state == stateFailed {
		m.mu.Unlock()
		return
	}
	e.restarting = true
	m.mu.Unlock()
	defer m.clearRestarting(e)

	for attempt := 0; ; attempt++ {
		if stopped := m.beginRestartAttempt(e); stopped {
			return
		}
		select {
		case <-ctx.Done():
			return
		case <-time.After(m.backoff(attempt)):
		}
		if m.doLaunch(ctx, e) == nil {
			return
		}
		if m.recordRestartFailure(e) {
			return
		}
	}
}

// beginRestartAttempt marks the plugin not_serving for this attempt and reports
// whether it was concurrently stopped (abort the sequence).
func (m *Manager) beginRestartAttempt(e *pluginEntry) (stopped bool) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if e.stopped {
		return true
	}
	e.state = stateNotServing
	e.lastChecked = m.now()
	return false
}

// recordRestartFailure increments the failure counters and, on the 3rd
// consecutive failure, marks the plugin failed and clears the dead handle.
// It reports whether the plugin is now failed (sequence should stop).
func (m *Manager) recordRestartFailure(e *pluginEntry) (failed bool) {
	m.mu.Lock()
	defer m.mu.Unlock()
	e.restarts++
	e.consecFails++
	if e.consecFails >= maxRestarts {
		e.state = stateFailed
		e.message = "plugin failed: 3 consecutive restart attempts unsuccessful"
		e.rp = nil
		return true
	}
	e.lastChecked = m.now()
	return false
}

func (m *Manager) clearRestarting(e *pluginEntry) {
	m.mu.Lock()
	e.restarting = false
	m.mu.Unlock()
}

// defaultLaunch is the production launchFunc: it spawns the plugin binary as a
// subprocess via go-plugin (magic-cookie substrate handshake, gRPC dial), and
// dispenses the typed capability clients the plugin declared. The client
// PluginSet is built ONLY from the plugin's declared capabilities
// (INV-caps-driven): a scanner-only plugin (base-scanner) yields the same
// {scanner: sdk.ScannerPlugin{}} set it always did (INV-ac3-base-scanner); a
// metadata_source plugin yields {metadata_source: sdk.MetadataSourcePlugin{}}.
// The command is built with an arg slice and never a shell (golang-security).
// Stderr is the entry's log ring (plugin-admin-surfaces D3): go-plugin copies
// the subprocess stderr into it in arbitrary chunks the ring reassembles into
// lines. The ring is per entry and never cleared, so a crash-restart's
// history survives (host-side observation only — the plugin contract is
// untouched).
func defaultLaunch(deps Deps) launchFunc {
	return func(_ context.Context, e *pluginEntry) (*runningPlugin, error) {
		cmd := exec.Command(e.binaryPath) // arg-slice only; go-plugin owns the process
		cl := goplugin.NewClient(&goplugin.ClientConfig{
			HandshakeConfig: goplugin.HandshakeConfig{
				ProtocolVersion:  goPluginProtocolVersion,
				MagicCookieKey:   deps.MagicCookieKey,
				MagicCookieValue: deps.MagicCookieValue,
			},
			Plugins:          clientPluginSet(e.caps),
			Cmd:              cmd,
			Stderr:           e.logs,
			AllowedProtocols: []goplugin.Protocol{goplugin.ProtocolGRPC},
			StartTimeout:     handshakeTimeout,
		})
		rp, err := dispense(cl, e.caps)
		if err != nil {
			cl.Kill()
			return nil, err
		}
		return rp, nil
	}
}

// clientPluginSet builds the go-plugin client PluginSet from a plugin's declared
// capabilities: each declared capability type maps to its dual-side adapter
// (scanner -> sdk.ScannerPlugin, metadata_source -> sdk.MetadataSourcePlugin).
// One entry per type; the gRPC service is bound by its fully-qualified name, so
// the dispense key is a per-type handle, not per-instance. Unknown types are
// omitted (a plugin is never asked to serve a capability it did not declare).
func clientPluginSet(caps []sdk.Capability) goplugin.PluginSet {
	set := goplugin.PluginSet{}
	for _, c := range caps {
		if a := adapterFor(c.Type); a != nil {
			set[c.Type] = a
		}
	}
	return set
}

// adapterFor returns the zero-value client adapter for a capability type, or nil
// if the type is not a known capability (the server-side Impl is unused on the
// client side, exactly like the original scanner-only set).
func adapterFor(capType string) goplugin.Plugin {
	switch capType {
	case scannerPluginKey:
		return &sdk.ScannerPlugin{}
	case metadataSourcePluginKey:
		return &sdk.MetadataSourcePlugin{}
	}
	return nil
}

// dispense starts the subprocess (cl.Client auto-starts), asserts the gRPC
// protocol, and dispenses each declared capability into the runningPlugin's
// typed client field (scanner and/or metadata), leaving the rest nil.
func dispense(cl *goplugin.Client, caps []sdk.Capability) (*runningPlugin, error) {
	proto, err := cl.Client()
	if err != nil {
		return nil, fmt.Errorf("go-plugin client: %w", err)
	}
	gc, ok := proto.(*goplugin.GRPCClient)
	if !ok {
		return nil, errors.New("go-plugin did not negotiate the gRPC protocol")
	}
	rp := &runningPlugin{
		pconn:  pluginv1.NewPluginClient(gc.Conn),
		exited: cl.Exited,
		kill:   cl.Kill,
	}
	seen := map[string]struct{}{}
	for _, c := range caps {
		if _, dup := seen[c.Type]; dup {
			continue
		}
		seen[c.Type] = struct{}{}
		if err := rp.assignCapability(proto, c.Type); err != nil {
			return nil, err
		}
	}
	return rp, nil
}

// assignCapability dispenses one capability type from the go-plugin client and
// stores its typed client. Unknown types are no-ops (clientPluginSet already
// filtered them; defending dispense keeps the two callers consistent). A nil
// current value guards against a duplicate-type declaration re-dispensing.
func (rp *runningPlugin) assignCapability(proto goplugin.ClientProtocol, capType string) error {
	switch capType {
	case scannerPluginKey:
		if rp.scanner != nil {
			return nil
		}
		raw, err := proto.Dispense(scannerPluginKey)
		if err != nil {
			return fmt.Errorf("dispense scanner: %w", err)
		}
		sc, ok := raw.(sdk.Scanner)
		if !ok {
			return fmt.Errorf("dispensed client %T is not an sdk.Scanner", raw)
		}
		rp.scanner = sc
	case metadataSourcePluginKey:
		if rp.metadata != nil {
			return nil
		}
		raw, err := proto.Dispense(metadataSourcePluginKey)
		if err != nil {
			return fmt.Errorf("dispense metadata_source: %w", err)
		}
		md, ok := raw.(sdk.MetadataSource)
		if !ok {
			return fmt.Errorf("dispensed client %T is not an sdk.MetadataSource", raw)
		}
		rp.metadata = md
	}
	return nil
}

// exponentialBackoff returns the §7.3 restart delay for a failed attempt index:
// initial 1s, factor 2, cap 60s, with up to 25% jitter so concurrent restarts
// desynchronize.
func exponentialBackoff(attempt int) time.Duration {
	d := backoffInitial
	for i := 0; i < attempt && d < backoffCap; i++ {
		d *= backoffFactor
	}
	if d > backoffCap {
		d = backoffCap
	}
	jitter := time.Duration(rand.Int63n(int64(d)/4 + 1))
	return d + jitter
}
